   294		}
   295		snapshotRel := filepath.ToSlash(filepath.Join(semanticDirName, semanticSnapshotsDir, snapshotID, semanticSnapshotName))
   296		snapshotPath := filepath.Join(storage.BrainDir, filepath.FromSlash(snapshotRel))
   297		if err := rejectExistingSymlinkPathComponents(storage.BrainDir, filepath.FromSlash(snapshotRel)); err != nil {
   298			return err
   299		}
   300		if err := writeFileAtomic(snapshotPath, raw, 0o600); err != nil {
