   313			Commit:           header.Commit,
   314			Tree:             header.Tree,
   315			Branch:           branch,
   316			DefaultBranch:    defaultBranch,
   317			DirtyWorktree:    dirty,
   318			Provider:         header.Provider,
   319			ProviderVersion:  header.ProviderVersion,
   320			SchemaVersion:    header.SchemaVersion,
   321			SnapshotPath:     snapshotRel,
   322			StorePath:        filepath.ToSlash(filepath.Join(generation, semanticSQLiteName)),
   323			GenerationPath:   generation,
   324			MetricsPath:      filepath.ToSlash(filepath.Join(generation, semanticMetricsName)),
   325			ParseCachePath:   filepath.ToSlash(filepath.Join(generation, "parse-cache")),
   326			OverlayPath:      overlayPath,
   327			Symbols:          counts.Symbols,
   328			Relations:        counts.Relations,
   329			Files:            counts.Files,
   330			Warnings:         warnings,
   331			PartialFailures:  header.PartialFailures,
   332			Capabilities:     header.Capabilities,
   333			NoEgressVerified: noEgress || indexOpts.skipSem,
   334			WorktreeMode:     worktreeMode,
   335			WorktreeHash:     worktreeHash,
   336		}
   337		if err := writeBrainSemanticSource(storage.BrainDir, storage.Key, source); err != nil {
   338			return err
   339		}
   340		if err := writeSemanticSnapshotManifest(storage.BrainDir, snapshotID, source); err != nil {
   341			return err
   342		}
   343		fmt.Fprintf(cmd.OutOrStdout(), "indexed semantic brain: %s\n", storage.BrainDir)
   344		fmt.Fprintf(cmd.OutOrStdout(), "snapshot: %s\n", snapshotRel)
   345		fmt.Fprintf(cmd.OutOrStdout(), "symbols: %d\nrelations: %d\n", source.Symbols, source.Relations)
   346		if len(source.Warnings) > 0 || len(source.PartialFailures) > 0 {
   347			fmt.Fprintf(cmd.OutOrStdout(), "warnings: %d\n", len(source.Warnings)+len(source.PartialFailures))
   348		}
   349		fmt.Fprintf(cmd.OutOrStdout(), "store: %s\n", source.StorePath)
   350		fmt.Fprintf(cmd.OutOrStdout(), "build_ms: %d\n", metrics.BuildMillis)
